cat /tmp/lit_map_current.yaml | python3 -c "
import sys, yaml
try:
    data = yaml.safe_load(sys.stdin)
    papers = data.get('papers', [])
    if papers is None:
        print('WARNING: papers is None (list-style YAML may need different parsing)')
    else:
        print(f'YAML valid. papers count: {len(papers) if isinstance(papers, list) else \"dict-style\"} ')
except Exception as e:
    print(f'YAML parse error: {e}')
" 2>/dev/null
